# ELIOT R33: install in the existing one-file BG_VOICE_UPDATE.cmd, then run 3 isolated previews.
# Trust gate: exactly the SHA256 of the current R32 single updater, no unknown versions accepted.
from __future__ import annotations
import base64,gzip,hashlib,os,pathlib,subprocess,sys,tempfile
from datetime import datetime,timezone
SOURCE_SHA='b1fa9aebb9fdf4d2214769d94fccb425b280e823594fe6f2901ee52a810a2c30'
TARGET_SHA='5d9fe951fdd79a052b7c88b1b04a846c2669f7e17e189ce128b2d5e1169bcd12'
ROUTE_SHA='3bcfd5654377176c475112f6f06c2f2db53877b115620077640ca3eb5ea4ab43'
ROUTE_B64=''
MARKER=b'# BGVOICE_V70_SINGLEFILE_INTEGRATION_END\r\n'
ANCHOR=b"        if '--eliot-r32-selftest' in sys.argv:\r\n"
FLAGS=b"        if '--eliot-r33-selftest' in sys.argv:\r\n            sys.exit(_eliot_r33_entry('selftest'))\r\n        if '--eliot-r33-preflight' in sys.argv:\r\n            sys.exit(_eliot_r33_entry('preflight'))\r\n        if '--eliot-r33-generate' in sys.argv:\r\n            sys.exit(_eliot_r33_entry('generate'))\r\n        if '--eliot-r33-work-shtorm' in sys.argv:\r\n            sys.exit(_eliot_r33_entry('shtorm-worker'))\r\n        if '--eliot-r33-work-qwen' in sys.argv:\r\n            sys.exit(_eliot_r33_entry('qwen-worker'))\r\n"
EMBED=('import sys;p=sys.argv.pop(1);t=open(p,encoding="utf-8-sig").read();'
       'exec(compile(t.split(chr(10)+"#BGVOICE_PYTHON_START"+chr(10),1)[1],p,"exec"),'
       '{"__name__":"__main__","__file__":p})')
def sha(b):return hashlib.sha256(b).hexdigest()
def patch_exact(b):
    if sha(b)!=SOURCE_SHA:raise RuntimeError('UNKNOWN_BG_VOICE_UPDATE_SHA '+sha(b))
    route=gzip.decompress(base64.b64decode(ROUTE_B64,validate=True))
    if sha(route)!=ROUTE_SHA or b'\r' in route:raise RuntimeError('R33_ROUTE_SHA_OR_FORMAT_HOLD')
    if b.count(MARKER)!=1 or b.count(ANCHOR)!=1 or b'_eliot_r33_entry' in b:raise RuntimeError('R33_EXPECTED_MARKERS_NOT_FOUND')
    result=b.replace(MARKER,route.replace(b'\n',b'\r\n')+b'\r\n'+MARKER,1).replace(ANCHOR,FLAGS+ANCHOR,1)
    if sha(result)!=TARGET_SHA:raise RuntimeError('R33_PATCH_OUTPUT_SHA_MISMATCH')
    return result
def call_embedded(cmd,flag):
    env=os.environ.copy();env.update({'PYTHONDONTWRITEBYTECODE':'1','HF_HUB_OFFLINE':'1','TRANSFORMERS_OFFLINE':'1','HF_DATASETS_OFFLINE':'1','HF_HUB_DISABLE_TELEMETRY':'1'})
    return subprocess.call([sys.executable,'-u','-c',EMBED,str(cmd),flag],env=env)
def main():
    if os.name!='nt' or sys.version_info<(3,11):
        print('ELIOT R33 HOLD: Windows Python 3.11+ required');return 2
    home=pathlib.Path.home();folder=home/'Downloads'/'BG_VOICE_RU_TTS_READY'/'bg_voice_release_v2';cmd=folder/'BG_VOICE_UPDATE.cmd'
    if not cmd.is_file() or cmd.is_symlink() or folder.is_symlink():
        print('ELIOT R33 HOLD: single updater missing/symlink:',cmd,flush=True);return 2
    original=cmd.read_bytes();oldsha=sha(original)
    if oldsha==TARGET_SHA:
        print('ELIOT R33 exact single updater already installed; no patch needed.',flush=True)
    elif oldsha==SOURCE_SHA:
        updated=patch_exact(original)
        backups=home/'Documents'/'BG_VOICE_RU'/'FULL_PRODUCTION'/'ELIOT_R33_UPDATER_BACKUPS'
        if backups.is_symlink():raise RuntimeError('R33_BACKUP_DIR_SYMLINK')
        backups.mkdir(parents=True,exist_ok=True)
        backup=backups/('BG_VOICE_UPDATE_PRE_R33_'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ')+'.bak')
        with backup.open('xb') as fh:fh.write(original);fh.flush();os.fsync(fh.fileno())
        if sha(backup.read_bytes())!=SOURCE_SHA:raise RuntimeError('R33_BACKUP_SHA_FAILURE')
        pending=folder/('BG_VOICE_UPDATE.cmd.R33_'+str(os.getpid())+'.pending')
        if pending.exists():raise RuntimeError('R33_PENDING_ALREADY_EXISTS')
        try:
            with pending.open('xb') as fh:fh.write(updated);fh.flush();os.fsync(fh.fileno())
            if sha(pending.read_bytes())!=TARGET_SHA or sha(cmd.read_bytes())!=SOURCE_SHA:raise RuntimeError('R33_CONCURRENT_MODIFICATION_HOLD')
            os.replace(pending,cmd)
        finally:pending.unlink(missing_ok=True)
        print('ELIOT R33 patched EXACT R32 single updater; backup SHA verified:',backup,flush=True)
    else:
        print('ELIOT R33 HOLD UNKNOWN_CMD_SHA256='+oldsha+'; NO modification.',flush=True);return 2
    if sha(cmd.read_bytes())!=TARGET_SHA:raise RuntimeError('R33_CMD_SHA_MISMATCH')
    for flag in ('--eliot-r33-selftest','--eliot-r33-preflight'):
        rc=call_embedded(cmd,flag)
        if rc:
            print('ELIOT R33 HOLD at',flag,'rc',rc,'synthesis not started',flush=True);return rc
    print('ELIOT R33: ONE cinematic IWINTRO_G08, new Qwen RU-stress model + repaired Shtorm control.',flush=True)
    rc=call_embedded(cmd,'--eliot-r33-generate')
    if rc:print('ELIOT R33 HOLD rc',rc,'successful WAVs cached, original ZIP unchanged until all three succeed.',flush=True)
    else:print('ELIOT R33 SUCCESS: 3 candidate WAVs in single SEND_TO_CHATGPT_BG_VOICE_RU.zip; no game changes.',flush=True)
    return rc
if __name__=='__main__':
    try:raise SystemExit(main())
    except KeyboardInterrupt:print('ELIOT R33 INTERRUPTED. Old report/game preserved.');raise SystemExit(130)
    except Exception as exc:print('ELIOT R33 FAIL CLOSED',type(exc).__name__,str(exc)[:320],flush=True);raise SystemExit(2)
